    '雷声走远了，我数着屋顶上剩下的那点滴答声。',
    '湿漉漉的地面反着光，像刚被人仔仔细细擦过。',
    '谢谢这场雨，替我把那些说不出口的话都下了。',
    '雨后树上的叶子亮得反光，像刚打过一层蜡。',
    '雷雨天窝着的那个下午，是被允许的一次休息。',
    '雨滴从屋檐落下来，一滴一滴，我数着说谢谢。',
    '雨过之后的空气里带着一点甜，我闻了很久。',
    '谢谢闪电替我照亮的那一瞬，虽然只有一秒。',
